CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_ISTANZE_OPE_RUOLI (IDCOMUNE, IDRUOLO, CODICERESPONSABILE, CODICEISTANZA) AS SELECT RR.IDCOMUNE,RR.IDRUOLO,RR.CODICERESPONSABILE,IR.CODICEISTANZA FROM RESPONSABILIRUOLI RR INNER JOIN ISTANZERUOLI IR ON RR.IDCOMUNE =IR.IDCOMUNE AND RR.IDRUOLO = IR.IDRUOLO INNER JOIN RUOLI R ON R.IDCOMUNE=IR.IDCOMUNE AND R.ID =IR.IDRUOLO AND (R.READONLY=0 OR (R.FLAG_GESTMOVIMENTI=1 OR R.FLAG_DISGESTMOVAMM =1));
CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_ISTANZECONCESSIONILISTA as 
SELECT 99999999 as PROGRESSIVO,AUTORIZZAZIONI.AUTORIZRESPONSABILE as CONC_AUTORIZRESPONSABILE,AUTORIZZAZIONI.IDCOMUNE,AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE as ICONC_CODICECAUSALE,ifnull(AUTORIZZAZIONI.DATA_CESSAZIONE,STR_TO_DATE('31/12/9999','%d/%m/%Y')) as DATA_STORICO,ISTANZE.SOFTWARE,ISTANZE.CODICEISTANZA as IST_CODICEISTANZA,ISTANZE.NUMEROISTANZA as IST_NUMEROISTANZA,ISTANZE.CODICERICHIEDENTE as IST_CODICERICHIEDENTE,AUTORIZZAZIONI.ID as CONC_ID,AUTORIZZAZIONI.AUTORIZNUMERO as CONC_NUMERO,AUTORIZZAZIONI.AUTORIZDATA as CONC_DATARILASCIO,AUTORIZZAZIONI.AUTORIZDATA as DATARILASCIO,AUTORIZZAZIONI.DATASCADENZA as CONC_DATASCADENZA,AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE as CONC_CODICETIPO,CONCESSIONITIPI.DESCRIZIONE as CONC_TIPO,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA as CONC_STAGIONALEA,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA as CONC_STAGIONALEDA,AUTORIZZAZIONI.FLAG_ATTIVA as CONC_ATTIVA,AUTORIZZAZIONI.FK_CODICEANAGRAFE as CONC_CODICETITOLARE,AUTORIZZAZIONI.FKIDREGISTRO as CONC_FKIDREGISTRO,CONC_REGISTRO.TR_DESCRIZIONE as CONC_REGISTRO,CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) as CONC_TITOLARE,TITOLARE.CODICEFISCALE as CONC_TIT_CF,TITOLARE.PARTITAIVA as CONC_TIT_PIVA,TITOLARE.TIPOANAGRAFE as CONC_TIT_TIPOANAGRAFE,AUT_COLLEGATA.AUTORIZNUMERO as AUT_NUMERO,AUT_COLLEGATA.AUTORIZDATA as AUT_DATA,AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO as AUT_CODREGISTRO,TIPOLOGIAREGISTRI.TR_DESCRIZIONE as AUT_REGISTRO,CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) as IST_NOMINATIVO,IST_RICHIEDENTE.TIPOANAGRAFE as IST_RIC_TIPOANAGRAFE,CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) as IST_NOMINATIVOAZIENDA,IST_AZIENDA.TIPOANAGRAFE as IST_AZI_TIPOANAGRAFE,IST_RICHIEDENTE.CODICEFISCALE as IST_CODICEFISCALE,IST_RICHIEDENTE.PARTITAIVA as IST_PARTITAIVA,CAUS_ATTUALE.DESCRIZIONE as ICONC_CAUSALE,AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE as ICONC_CODICECAUSALESTORICO,CAUS_STORICO.DESCRIZIONE as ICONC_CAUSALESTORICO,AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO as CONC_IDMERCATO,MERCATI.DESCRIZIONE as CONC_MERCATO,MERCATI.ATTIVO as MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO as CONC_IDPOSTEGGIO,MERCATI_D.CODICEPOSTEGGIO as CONC_POSTEGGIO,MERCATI_D.LARGHEZZA as CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA as CONC_POS_LUNGHEZZA,MERCATI_D.SUPERFICIE as CONC_POS_SUPERFICIE,MERCATI_D.FKCODICETIPOSPAZIO as POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO as POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO as CONC_IDMERCATIUSO,MERCATI_USO.DESCRIZIONE as CONC_DESCRIZIONEUSO,MERCATI_USO.PESO as PESO_MERCATO,MERCATI_USO.FKCODICEUSO as MERC_IDUSO,MERCATI_D.FKCODICESTRADARIO as CONC_POS_CODICESTRADARIO,MERCATI_D.NOTE as CONC_POS_NOTE FROM AUTORIZZAZIONI_CONCESSIONI LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA LEFT OUTER JOIN TIPOLOGIAREGISTRI ON AUT_COLLEGATA.IDCOMUNE=TIPOLOGIAREGISTRI.IDCOMUNE  AND AUT_COLLEGATA.FKIDREGISTRO=TIPOLOGIAREGISTRI.TR_ID ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE=AUT_COLLEGATA.IDCOMUNE  AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA=AUT_COLLEGATA.ID,AUTORIZZAZIONI LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI.IDCOMUNE=CAUS_STORICO.IDCOMUNE  AND AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE=CAUS_STORICO.CODICECAUSALE,MERCATI_D LEFT OUTER JOIN POSTEGGITIPOSPAZIO ON MERCATI_D.IDCOMUNE=POSTEGGITIPOSPAZIO.IDCOMUNE  AND MERCATI_D.FKCODICETIPOSPAZIO=POSTEGGITIPOSPAZIO.CODICE,ISTANZE LEFT OUTER JOIN ANAGRAFE IST_AZIENDA ON ISTANZE.IDCOMUNE=IST_AZIENDA.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=IST_AZIENDA.CODICEANAGRAFE,CONCESSIONITIPI,TIPOLOGIAREGISTRI CONC_REGISTRO,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE,ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_USO WHERE CONC_REGISTRO.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND CONC_REGISTRO.TR_ID = AUTORIZZAZIONI.FKIDREGISTRO AND AUTORIZZAZIONI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AND ISTANZE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND ISTANZE.CODICEISTANZA = AUTORIZZAZIONI.FKIDISTANZA AND IST_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND IST_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND MERCATI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI.CODICEMERCATO = AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AND MERCATI_D.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_D.IDPOSTEGGIO = AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AND MERCATI_USO.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_USO.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO 
UNION
SELECT AUTORIZZAZIONI_SUBENTRI.ID as PROGRESSIVO,AUTORIZZAZIONI_SUBENTRI.AUTORIZRESPONSABILE as CONC_AUTORIZRESPONSABILE,AUTORIZZAZIONI_SUBENTRI.IDCOMUNE,AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE as ICONC_CODICECAUSALE,AUTORIZZAZIONI_SUBENTRI.DATA_CESSAZIONE as DATA_STORICO,ISTANZE.SOFTWARE,ISTANZE.CODICEISTANZA as IST_CODICEISTANZA,ISTANZE.NUMEROISTANZA as IST_NUMEROISTANZA,ISTANZE.CODICERICHIEDENTE as IST_CODICERICHIEDENTE,AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE as CONC_ID,AUTORIZZAZIONI_SUBENTRI.AUTORIZNUMERO as CONC_NUMERO,AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA as CONC_DATARILASCIO,AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA as DATARILASCIO,AUTORIZZAZIONI_SUBENTRI.DATASCADENZA as CONC_DATASCADENZA,AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE as CONC_CODICETIPO,CONCESSIONITIPI.DESCRIZIONE as CONC_TIPO,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA as CONC_STAGIONALEA,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA as CONC_STAGIONALEDA,0 as CONC_ATTIVA,AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE as CONC_CODICETITOLARE,AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO as CONC_FKIDREGISTRO,CONC_REGISTRO.TR_DESCRIZIONE as CONC_REGISTRO,CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) as CONC_TITOLARE,TITOLARE.CODICEFISCALE as CONC_TIT_CF,TITOLARE.PARTITAIVA as CONC_TIT_PIVA,TITOLARE.TIPOANAGRAFE as CONC_TIT_TIPOANAGRAFE,AUT_COLLEGATA.AUTORIZNUMERO as AUT_NUMERO,AUT_COLLEGATA.AUTORIZDATA as AUT_DATA,AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO as AUT_CODREGISTRO,TIPOLOGIAREGISTRI.TR_DESCRIZIONE as AUT_REGISTRO,CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) as IST_NOMINATIVO,IST_RICHIEDENTE.TIPOANAGRAFE as IST_RIC_TIPOANAGRAFE,CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) as IST_NOMINATIVOAZIENDA,IST_AZIENDA.TIPOANAGRAFE as IST_AZI_TIPOANAGRAFE,IST_RICHIEDENTE.CODICEFISCALE as IST_CODICEFISCALE,IST_RICHIEDENTE.PARTITAIVA as IST_PARTITAIVA,CAUS_ATTUALE.DESCRIZIONE as ICONC_CAUSALE,AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE as ICONC_CODICECAUSALESTORICO,CAUS_STORICO.DESCRIZIONE as ICONC_CAUSALESTORICO,AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO as CONC_IDMERCATO,MERCATI.DESCRIZIONE as CONC_MERCATO,MERCATI.ATTIVO as MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO as CONC_IDPOSTEGGIO,MERCATI_D.CODICEPOSTEGGIO as CONC_POSTEGGIO,MERCATI_D.LARGHEZZA as CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA as CONC_POS_LUNGHEZZA,MERCATI_D.SUPERFICIE as CONC_POS_SUPERFICIE,MERCATI_D.FKCODICETIPOSPAZIO as POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO as POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO as CONC_IDMERCATIUSO,MERCATI_USO.DESCRIZIONE as CONC_DESCRIZIONEUSO,MERCATI_USO.PESO as PESO_MERCATO,MERCATI_USO.FKCODICEUSO as MERC_IDUSO,MERCATI_D.FKCODICESTRADARIO as CONC_POS_CODICESTRADARIO,MERCATI_D.NOTE as CONC_POS_NOTE FROM AUTORIZZAZIONI_CONCESSIONI LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA LEFT OUTER JOIN TIPOLOGIAREGISTRI ON AUT_COLLEGATA.IDCOMUNE=TIPOLOGIAREGISTRI.IDCOMUNE  AND AUT_COLLEGATA.FKIDREGISTRO=TIPOLOGIAREGISTRI.TR_ID ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE=AUT_COLLEGATA.IDCOMUNE  AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA=AUT_COLLEGATA.ID,AUTORIZZAZIONI_SUBENTRI LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE=CAUS_STORICO.IDCOMUNE  AND AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE=CAUS_STORICO.CODICECAUSALE,MERCATI_D LEFT OUTER JOIN POSTEGGITIPOSPAZIO ON MERCATI_D.IDCOMUNE=POSTEGGITIPOSPAZIO.IDCOMUNE  AND MERCATI_D.FKCODICETIPOSPAZIO=POSTEGGITIPOSPAZIO.CODICE,ISTANZE LEFT OUTER JOIN ANAGRAFE IST_AZIENDA ON ISTANZE.IDCOMUNE=IST_AZIENDA.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=IST_AZIENDA.CODICEANAGRAFE,CONCESSIONITIPI,TIPOLOGIAREGISTRI CONC_REGISTRO,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE,ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_USO WHERE CONC_REGISTRO.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND CONC_REGISTRO.TR_ID = AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO AND AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE AND ISTANZE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND ISTANZE.CODICEISTANZA = AUTORIZZAZIONI_SUBENTRI.FKIDISTANZA AND IST_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND IST_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND MERCATI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI.CODICEMERCATO = AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AND MERCATI_D.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_D.IDPOSTEGGIO = AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AND MERCATI_USO.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_USO.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO;

CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_CONCESSIONILISTA AS 
SELECT IDCOMUNE, SOFTWARE, PROGRESSIVO, CONC_ID, CONC_NUMERO, CONC_DATARILASCIO, CONC_DATASCADENZA, CONC_CODICETIPO, CONC_TIPO, CONC_STAGIONALEA, CONC_STAGIONALEDA, CONC_ATTIVA, CONC_CODICETITOLARE, CONC_TITOLARE, CONC_TIT_CF, CONC_TIT_PIVA, CONC_TIT_TIPOANAGRAFE, CONC_FKIDREGISTRO, CONC_REGISTRO, AUT_NUMERO, AUT_DATA, AUT_CODREGISTRO, AUT_REGISTRO, IST_CODICEISTANZA, IST_NUMEROISTANZA, IST_CODICERICHIEDENTE, IST_NOMINATIVO, IST_CODICEFISCALE, IST_PARTITAIVA, IST_RIC_TIPOANAGRAFE, ICONC_CODICECAUSALE, ICONC_CAUSALE, ICONC_CODICECAUSALESTORICO, ICONC_CAUSALESTORICO, CONC_IDMERCATO, CONC_MERCATO, MERC_ATTIVO, CONC_IDPOSTEGGIO, CONC_POSTEGGIO, CONC_POS_LARGHEZZA, CONC_POS_LUNGHEZZA, CONC_POS_SUPERFICIE, POST_IDTIPOSPAZIO, POST_TIPOSPAZIO, CONC_IDMERCATIUSO, CONC_DESCRIZIONEUSO, PESO_MERCATO, MERC_IDUSO, CONC_POS_CODICESTRADARIO, DATA_STORICO FROM VW_ISTANZECONCESSIONILISTA;

ALTER TABLE ISTANZESTRADARIO ADD ID_PUNTO_SIT VARCHAR(50);

ALTER TABLE COMUNIASSOCIATI ADD CODICE_ENTE_PAYER VARCHAR(5);

