(
  IDCOMUNE VARCHAR(6) NOT NULL,
  ID NUMERIC(10,0) NOT NULL,
  FKCODICEMERCATO NUMERIC(4, 0) NOT NULL, 
  FK_D2C_ID NUMERIC(10, 0) NOT NULL, 
  CONSTRAINT MERCATI_D2C_ASSEGNAZ_PK PRIMARY KEY 
  (
    IDCOMUNE, 
    ID 
  ) 
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

ALTER TABLE MERCATI_D2C_ASSEGNAZ ADD CONSTRAINT FK_MERC_D2C_ASS_MERCATI FOREIGN KEY(IDCOMUNE , FKCODICEMERCATO) REFERENCES MERCATI (IDCOMUNE, CODICEMERCATO );
ALTER TABLE MERCATI_D2C_ASSEGNAZ ADD CONSTRAINT FK_MERC_D2C_ASS_DYN2_CAMPI FOREIGN KEY (IDCOMUNE , FK_D2C_ID) REFERENCES DYN2_CAMPI (IDCOMUNE , ID);

ALTER TABLE MERCATI  ADD FK_D2CID_PREF_USO NUMERIC(10, 0);

ALTER TABLE MERCATI ADD CONSTRAINT FK_MERCATI_DYN2_CAMPI FOREIGN KEY (IDCOMUNE , FK_D2CID_PREF_USO) REFERENCES DYN2_CAMPI (IDCOMUNE , ID);

ALTER TABLE MERCATI_D  ADD PESO NUMERIC(4, 0);

CREATE TABLE MERCATI_D_CRITASS 
(
  IDCOMUNE VARCHAR(6) NOT NULL,
  ID NUMERIC(10,0) NOT NULL,
  FK_IDPOSTEGGIO NUMERIC(6, 0) NOT NULL, 
  FK_D2C_ID NUMERIC(10, 0) NOT NULL,
  VALORE VARCHAR(100) NOT NULL,
  VALOREDECODIFICATO VARCHAR(100),
  FLAG_CONSENTITO NUMERIC(1, 0), 
  CONSTRAINT MERCATI_D_CRITASS_PK PRIMARY KEY 
  (
    IDCOMUNE, 
    ID 
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

ALTER TABLE MERCATI_D_CRITASS ADD CONSTRAINT FK_MERC_D_CRITASS_DYN2_CAMPI FOREIGN KEY (IDCOMUNE , FK_D2C_ID) REFERENCES DYN2_CAMPI(IDCOMUNE , ID);
ALTER TABLE MERCATI_D_CRITASS ADD CONSTRAINT FK_MERC_D_CRITASS_MERCATID FOREIGN KEY (IDCOMUNE , FK_IDPOSTEGGIO) REFERENCES MERCATI_D(IDCOMUNE , IDPOSTEGGIO);


CREATE TABLE COMUNIASSOCIAZIONI (CODICEASSOCIAZIONE VARCHAR(5) NOT NULL, ASSOCIAZIONE VARCHAR(128) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8;
ALTER TABLE COMUNIASSOCIAZIONI ADD( CONSTRAINT PK_COMASSOCIAZIONI PRIMARY KEY (CODICEASSOCIAZIONE));
CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_ENTILOCALI AS SELECT CODICECOMUNE, COMUNE FROM COMUNI UNION SELECT CODICEASSOCIAZIONE AS CODICECOMUNE, ASSOCIAZIONE AS COMUNE FROM COMUNIASSOCIAZIONI;

