ALTER TABLE FO_ARJ_DOMANDE_ONERI ADD CONSTRAINT FK_FADO_TCASUONERICOID FOREIGN KEY (IDCOMUNE, FK_CAUSALEONERI) REFERENCES TIPICAUSALIONERI(IDCOMUNE, CO_ID); 
